mapper.select:
/* DgnssMapper.selectAllStdtList */
SELECT stdt_id
FROM   aidt_lms.tc_cla_mb_info
WHERE  cla_id = #{claId}
       AND actvtn_at = 'Y'

/* DgnssMapper.selectDgnssStdtList */
SELECT tdri.stdt_id
FROM aidt_diagnosis.tb_dgnss_info tdi
INNER JOIN aidt_diagnosis.tb_dgnss_result_info tdri ON tdi.id = tdri.dgnss_id
WHERE tdi.cla_id = #{claId}
GROUP BY tdri.stdt_id

mapper.delete:
/* etcMapper.deleteTargetStListResultInfo */
DELETE FROM aidt_diagnosis.tb_dgnss_result_info
WHERE stdt_id in (

	#{item}
)

/* etcMapper.deleteTargetStListAnswer */
DELETE FROM aidt_diagnosis.tb_dgnss_answer
WHERE MEM_ID in (

	#{item}
)

mapper.select:
/* DgnssMapper.selectActvStdtCnt */
SELECT COUNT(*)
FROM aidt_lms.tc_cla_mb_info tcmi
WHERE tcmi.cla_id = #{claId}
AND tcmi.actvtn_at = 'Y'

mapper.insert:
/* DgnssMapper.insertDgnssInfo */ INSERT INTO `aidt_diagnosis`.tb_dgnss_info ( cla_id, tc_id, ord_no , paper_idx
) VALUES ( #{claId}, #{tcId}, #{ordNo} , #{paperIdx}
)

mapper.select:
/* DgnssMapper.selectExistsDgnssInfo */
SELECT COUNT(*)
FROM `aidt_diagnosis`.`tb_dgnss_info`
WHERE cla_id = #{claId}
  AND tc_id = #{tcId}
  AND ord_no = #{ordNo}
  AND paper_idx = #{paperIdx}

/* DgnssMapper.selectTcId */
SELECT user_id
FROM `aidt_lms`.tc_cla_info
WHERE cla_id = #{claId}

mapper.insert:
/* DgnssMapper.insertDgnssResult */ INSERT INTO `aidt_diagnosis`.`tb_dgnss_omr` ( MEM_ID, CLASS_NO , PAPER_IDX
) VALUES ( #{stdtId}, #{claId} , '5'
)

		/* DgnssMapper.insertDgnssResult */
		INSERT INTO `aidt_diagnosis`.tb_dgnss_result_info
        (
            dgnss_id, 
            stdt_id, 
            omr_id
        )
        VALUES
        (
            #{dgnssId}, 
            #{stdtId}, 
            #{omrIdx}
        )

/* DgnssMapper.insertDgnssAnswer */ INSERT INTO `aidt_diagnosis`.`tb_dgnss_answer` ( MEM_ID, DGNSS_RESULT_ID, DGNSS_ORD, SCH_GRADE, TEST_IDX , DGNSS_ID, PAPER_IDX
) VALUES ( #{stdtId}, #{dgnssResultId}, #{ordNo}, #{schGrade}, #{dgnssId} , 'DGNSS_10', '5'
)

mapper.select:
/* DgnssMapper.selectTcDgnssInfoOne */ SELECT a1.id AS dgnssId, a1.ord_no AS ordNo, a1.cla_id AS claId, a1.dgnss_at AS dgnssAt, Date_format(dgnss_st_dt, "%Y-%m-%d %H:%i:%s") AS dgnssStDt, Date_format(dgnss_ed_dt, "%Y-%m-%d %H:%i:%s") AS dgnssEdDt, Count(DISTINCT CASE WHEN b1.subm_at = 'Y' THEN b1.stdt_id END) AS stSubmCnt FROM `aidt_diagnosis`.`tb_dgnss_info`a1 INNER JOIN aidt_diagnosis.tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN aidt_lms.tc_cla_mb_info c1 ON a1.cla_id = c1.cla_id AND b1.stdt_id = c1.stdt_id AND c1.actvtn_at = 'Y' WHERE a1.cla_id = #{claId}
AND a1.paper_idx = '1'
AND a1.paper_idx = '2'
AND a1.ord_no = #{ordNo} GROUP BY a1.id ORDER BY a1.id DESC LIMIT 1

mapper.update:
/* DgnssMapper.updateDgnssInfo */
UPDATE `aidt_diagnosis`.`tb_dgnss_info`
SET    dgnss_at = 'N',
       dgnss_ed_dt = NOW()
WHERE  id = #{dgnssId}

mapper.select:
/* DgnssMapper.selectStdtIdFromDgnssResultId */
SELECT stdt_id
FROM aidt_diagnosis.tb_dgnss_result_info
WHERE id = #{dgnssResultId}

