iagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 106, OMR.106) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 107, OMR.107) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 108, OMR.108) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 109, OMR.109) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 110, OMR.110) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 111, OMR.111) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 112, OMR.112) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 113, OMR.113) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 114, OMR.114) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 115, OMR.115) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 116, OMR.116) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 117, OMR.117) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 118, OMR.118) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 119, OMR.119) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 120, OMR.120) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 121, OMR.121) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 122, OMR.122) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 123, OMR.123) , ', ', `aidt_diagnosis`.FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 124, OMR.124) ,']') AS ANSWERS FROM `aidt_diagnosis`.`tb_dgnss_result_info` a1 INNER JOIN `aidt_diagnosis`.`tb_dgnss_omr` OMR ON a1.omr_id = OMR.OMR_IDX WHERE a1.id = #{dgnssResultId} )
, REPEATED_RESPONSE_YN = 'Y'
WHERE aa.DGNSS_RESULT_ID = #{dgnssResultId}

mapper.select:
/* DgnssMapper.selectAnswerIdx */
SELECT ANSWER_IDX
FROM `aidt_diagnosis`.`tb_dgnss_answer`
WHERE DGNSS_RESULT_ID = #{dgnssResultId}

/* DgnssMapper.getDgnssReportSection */
SELECT A1.MEM_ID, sri.num AS CLASS_NO, IFNULL(B.T_SCORE_01_01, -1) AS T_SCORE_01_01, IFNULL(B.T_SCORE_01_02, -1) AS T_SCORE_01_02, IFNULL(B.T_SCORE_02_01, -1) AS T_SCORE_02_01, IFNULL(B.T_SCORE_02_02, -1) AS T_SCORE_02_02, IFNULL(B.T_SCORE_02_03, -1) AS T_SCORE_02_03, IFNULL(B.T_SCORE_03_01, -1) AS T_SCORE_03_01, IFNULL(B.T_SCORE_03_02, -1) AS T_SCORE_03_02, IFNULL(B.T_SCORE_03_03, -1) AS T_SCORE_03_03, IFNULL(B.T_SCORE_04_01, -1) AS T_SCORE_04_01, IFNULL(B.T_SCORE_04_02, -1) AS T_SCORE_04_02, IFNULL(B.T_SCORE_05_01, -1) AS T_SCORE_05_01, IFNULL(C.T_SCORE_01_01_01, -1) AS T_SCORE_01_01_01, IFNULL(C.T_SCORE_01_01_02, -1) AS T_SCORE_01_01_02, IFNULL(C.T_SCORE_01_01_03, -1) AS T_SCORE_01_01_03, IFNULL(C.T_SCORE_01_02_01, -1) AS T_SCORE_01_02_01, IFNULL(C.T_SCORE_01_02_02, -1) AS T_SCORE_01_02_02, IFNULL(C.T_SCORE_01_02_03, -1) AS T_SCORE_01_02_03, IFNULL(C.T_SCORE_01_02_04, -1) AS T_SCORE_01_02_04, IFNULL(C.T_SCORE_02_01_01, -1) AS T_SCORE_02_01_01, IFNULL(C.T_SCORE_02_01_02, -1) AS T_SCORE_02_01_02, IFNULL(C.T_SCORE_02_01_03, -1) AS T_SCORE_02_01_03, IFNULL(C.T_SCORE_02_02_01, -1) AS T_SCORE_02_02_01, IFNULL(C.T_SCORE_02_02_02, -1) AS T_SCORE_02_02_02, IFNULL(C.T_SCORE_02_02_03, -1) AS T_SCORE_02_02_03, IFNULL(C.T_SCORE_02_02_04, -1) AS T_SCORE_02_02_04, IFNULL(C.T_SCORE_02_02_05, -1) AS T_SCORE_02_02_05, IFNULL(C.T_SCORE_02_03_01, -1) AS T_SCORE_02_03_01, IFNULL(C.T_SCORE_02_03_02, -1) AS T_SCORE_02_03_02, IFNULL(C.T_SCORE_02_03_03, -1) AS T_SCORE_02_03_03, IFNULL(C.T_SCORE_02_03_04, -1) AS T_SCORE_02_03_04, IFNULL(C.T_SCORE_03_01_01, -1) AS T_SCORE_03_01_01, IFNULL(C.T_SCORE_03_01_02, -1) AS T_SCORE_03_01_02, IFNULL(C.T_SCORE_03_01_03, -1) AS T_SCORE_03_01_03, IFNULL(C.T_SCORE_03_02_01, -1) AS T_SCORE_03_02_01, IFNULL(C.T_SCORE_03_02_02, -1) AS T_SCORE_03_02_02, IFNULL(C.T_SCORE_03_02_03, -1) AS T_SCORE_03_02_03, IFNULL(C.T_SCORE_03_02_04, -1) AS T_SCORE_03_02_04, IFNULL(C.T_SCORE_03_02_05, -1) AS T_SCORE_03_02_05, IFNULL(C.T_SCORE_03_03_01, -1) AS T_SCORE_03_03_01, IFNULL(C.T_SCORE_03_03_02, -1) AS T_SCORE_03_03_02, IFNULL(C.T_SCORE_04_01_01, -1) AS T_SCORE_04_01_01, IFNULL(C.T_SCORE_04_01_02, -1) AS T_SCORE_04_01_02, IFNULL(C.T_SCORE_04_01_03, -1) AS T_SCORE_04_01_03, IFNULL(C.T_SCORE_04_02_01, -1) AS T_SCORE_04_02_01, IFNULL(C.T_SCORE_04_02_02, -1) AS T_SCORE_04_02_02, IFNULL(C.T_SCORE_04_02_03, -1) AS T_SCORE_04_02_03, IFNULL(C.T_SCORE_05_01_01, -1) AS T_SCORE_05_01_01, IFNULL(C.T_SCORE_05_01_02, -1) AS T_SCORE_05_01_02, IFNULL(C.T_SCORE_05_01_03, -1) AS T_SCORE_05_01_03 FROM ( SELECT a1_1.id, a1_2.num, a1_1.stdt_id AS MEM_ID FROM aidt_diagnosis.tb_dgnss_result_info a1_1 INNER JOIN aidt_lms.stdt_reg_info a1_2 ON a1_1.stdt_id = a1_2.user_id INNER JOIN aidt_diagnosis.tb_dgnss_info tdi ON a1_1.dgnss_id = tdi.id INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON a1_1.stdt_id = tcmi.stdt_id AND tdi.cla_id = tcmi.cla_id AND tcmi.actvtn_at = 'Y' WHERE a1_1.dgnss_id = #{TEST_IDX} AND EXISTS ( SELECT 1 FROM aidt_diagnosis.tb_dgnss_answer_report tdar WHERE tdar.ANSWER_IDX = a1_1.id ) ) A1 LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01 FROM aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 4 GROUP BY DA.MEM_ID ) B ON A1.MEM_ID = B.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_04, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_04, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_05, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_05, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_03, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_03, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_01, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_02, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_03 FROM aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 5 GROUP BY DA.MEM_ID ) C ON B.MEM_ID = C.MEM_ID INNER JOIN aidt_lms.stdt_reg_info sri ON A1.MEM_ID = sri.user_id ORDER BY A1.num;
SELECT A1.MEM_ID, sri.num AS CLASS_NO, IFNULL(A.T_SCORE_01, -1) AS T_SCORE_01, IFNULL(A.T_SCORE_02, -1) AS T_SCORE_02, IFNULL(A.T_SCORE_03, -1) AS T_SCORE_03, IFNULL(B.T_SCORE_01_01, -1) AS T_SCORE_01_01, IFNULL(B.T_SCORE_01_02, -1) AS T_SCORE_01_02, IFNULL(B.T_SCORE_02_01, -1) AS T_SCORE_02_01, IFNULL(B.T_SCORE_02_02, -1) AS T_SCORE_02_02, IFNULL(B.T_SCORE_03_01, -1) AS T_SCORE_03_01, IFNULL(B.T_SCORE_03_02, -1) AS T_SCORE_03_02, IFNULL(C.T_SCORE_01_01_01, -1) AS T_SCORE_01_01_01, IFNULL(C.T_SCORE_01_01_02, -1) AS T_SCORE_01_01_02, IFNULL(C.T_SCORE_01_01_03, -1) AS T_SCORE_01_01_03, IFNULL(C.T_SCORE_01_02_01, -1) AS T_SCORE_01_02_01, IFNULL(C.T_SCORE_01_02_02, -1) AS T_SCORE_01_02_02, IFNULL(C.T_SCORE_01_02_03, -1) AS T_SCORE_01_02_03, IFNULL(C.T_SCORE_02_01_01, -1) AS T_SCORE_02_01_01, IFNULL(C.T_SCORE_02_01_02, -1) AS T_SCORE_02_01_02, IFNULL(C.T_SCORE_02_01_03, -1) AS T_SCORE_02_01_03, IFNULL(C.T_SCORE_02_02_01, -1) AS T_SCORE_02_02_01, IFNULL(C.T_SCORE_02_02_02, -1) AS T_SCORE_02_02_02, IFNULL(C.T_SCORE_02_02_03, -1) AS T_SCORE_02_02_03, IFNULL(C.T_SCORE_03_01_01, -1) AS T_SCORE_03_01_01, IFNULL(C.T_SCORE_03_01_02, -1) AS T_SCORE_03_01_02, IFNULL(C.T_SCORE_03_01_03, -1) AS T_SCORE_03_01_03, IFNULL(C.T_SCORE_03_02_01, -1) AS T_SCORE_03_02_01, IFNULL(C.T_SCORE_03_02_02, -1) AS T_SCORE_03_02_02, IFNULL(C.T_SCORE_03_02_03, -1) AS T_SCORE_03_02_03, IFNULL(C.T_SCORE_03_02_04, -1) AS T_SCORE_03_02_04, IFNULL(C.T_SCORE_03_02_05, -1) AS T_SCORE_03_02_05 FROM ( SELECT a1_1.id, a1_2.num, a1_1.stdt_id AS MEM_ID FROM aidt_diagnosis.tb_dgnss_result_info a1_1 INNER JOIN aidt_lms.stdt_reg_info a1_2 ON a1_1.stdt_id = a1_2.user_id INNER JOIN aidt_diagnosis.tb_dgnss_info tdi ON a1_1.dgnss_id = tdi.id INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON a1_1.stdt_id = tcmi.stdt_id AND tdi.cla_id = tcmi.cla_id AND tcmi.actvtn_at = 'Y' WHERE a1_1.dgnss_id = #{TEST_IDX} AND EXISTS ( SELECT 1 FROM aidt_diagnosis.tb_dgnss_answer_report tdar WHERE tdar.ANSWER_IDX = a1_1.id ) ) A1 LEFT JOIN ( SELECT DA.MEM_ID, IFNULL(MAX( CASE WHEN DS.CLASS3 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_01, IFNULL(MAX( CASE WHEN DS.CLASS3 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_02, IFNULL(MAX( CASE WHEN DS.CLASS3 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_03 FROM aidt_diagnosis.TB_DGNSS_ANSWER DA LEFT JOIN aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR ON DAR.ANSWER_IDX = DA.ANSWER_IDX LEFT JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 3 GROUP BY DA.MEM_ID ) A ON A1.MEM_ID = A.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02 FROM aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 4 GROUP BY DA.MEM_ID ) B ON A.MEM_ID = B.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_05 FROM aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 5 GROUP BY DA.MEM_ID ) C ON A.MEM_ID = C.MEM_ID INNER JOIN aidt_lms.stdt_reg_info sri ON A1.MEM_ID = sri.user_id ORDER BY A1.num

/* DgnssMapper.getDgnssFirstTest */
SELECT tdi.id
FROM aidt_diagnosis.tb_dgnss_info tdi
WHERE tdi.tc_id = (
	SELECT tc_id
	FROM aidt_diagnosis.tb_dgnss_info tdi2
	WHERE tdi2.id = #{TEST_IDX}
)
AND tdi.paper_idx = (
	SELECT paper_idx
	FROM aidt_diagnosis.tb_dgnss_info tdi2
	WHERE tdi2.id = #{TEST_IDX}
)
AND tdi.cla_id = #{claId}
AND tdi.ord_no = 1

/* DgnssMapper.getDgnssReportStatByTest */ SELECT STAT.SECTION_ID , DS.CLASS3, DS.CLASS4, DS.CLASS5, DS.DEPTH , ROUND(STAT.T_SCORE, 0) AS T_SCORE , IFNULL(ROUND(STAT_FIRST.T_SCORE, 0), 0) AS T_SCORE_FIRST , ROUND(STAT.T_SCORE, 0) - IFNULL(ROUND(STAT_FIRST.T_SCORE, 0), ROUND(STAT.T_SCORE, 0)) AS T_SCORE_GAP FROM ( SELECT DAR.SECTION_ID, IF(ROUND(AVG(DAR.T_SCORE), 2) < 0, 0, ROUND(AVG(DAR.T_SCORE))) AS T_SCORE FROM aidt_diagnosis.tb_dgnss_info DT INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DT.id = DA.TEST_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR ON DA.ANSWER_IDX = DAR.ANSWER_IDX INNER JOIN aidt_diagnosis.tb_dgnss_result_info tdri ON DT.id = tdri.dgnss_id INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON DT.cla_id = tcmi.cla_id AND tdri.stdt_id = tcmi.stdt_id AND tcmi.actvtn_at = 'Y' WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = #{DEPTH}
AND DA.COCH_DGNSS_QESITM01_MARK <> '주의' AND DA.COCH_DGNSS_QESITM02_MARK <> '주의' AND DA.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY DAR.SECTION_ID) STAT LEFT JOIN (SELECT DAR.SECTION_ID, IF(ROUND(AVG(DAR.T_SCORE), 2) < 0, 0, ROUND(AVG(DAR.T_SCORE))) AS T_SCORE FROM aidt_diagnosis.tb_dgnss_info DT INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER DA ON DT.id = DA.TEST_IDX INNER JOIN aidt_diagnosis.TB_DGNSS_ANSWER_REPORT DAR ON DA.ANSWER_IDX = DAR.ANSWER_IDX INNER JOIN aidt_diagnosis.tb_dgnss_result_info tdri ON DT.id = tdri.dgnss_id INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON DT.cla_id = tcmi.cla_id AND tdri.stdt_id = tcmi.stdt_id AND tcmi.actvtn_at = 'Y' WHERE DA.TEST_IDX = #{FIRST_IDX} AND DAR.DEPTH = #{DEPTH}
AND DA.COCH_DGNSS_QESITM01_MARK <> '주의' AND DA.COCH_DGNSS_QESITM02_MARK <> '주의' AND DA.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY DAR.SECTION_ID) STAT_FIRST ON STAT.SECTION_ID = STAT_FIRST.SECTION_ID INNER JOIN aidt_diagnosis.TB_DGNSS_SECTION DS ON STAT.SECTION_ID = DS.SECTION_ID ORDER BY STAT.SECTION_ID

