/* DgnssMapper.selectStQuesList */ SELECT aa.* FROM ( SELECT b1.`NO` , c1.QESITM_NM , COUNT(*) OVER () AS fullCount FROM `aidt_diagnosis`.`tb_dgnss_paper` a1 INNER JOIN `aidt_diagnosis`.`tb_dgnss_paper_detail` b1 ON a1.PAPER_IDX = b1.PAPER_IDX INNER JOIN `aidt_diagnosis`.`tb_dgnss_problem` c1 ON b1.PROBLEM_IDX = c1.PROBLEM_IDX WHERE 1=1
AND a1.PAPER_IDX = 5 ORDER BY b1.`no` LIMIT 119
AND a1.PAPER_IDX = 6 ORDER BY b1.`no`
) aa LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

mapper.update:
/* DgnssMapper.updateStStart */
UPDATE `aidt_diagnosis`.`tb_dgnss_result_info`
SET eak_stts_cd = 2
	, eak_at = 'Y'
	, eak_st_dt = NOW()
WHERE id = #{dgnssResultId}

mapper.select:
/* DgnssMapper.selectPaperIdxFromResultId */
SELECT a1.paper_idx
FROM aidt_diagnosis.tb_dgnss_info a1
	INNER JOIN aidt_diagnosis.tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id
WHERE b1.id = #{dgnssResultId}

/* DgnssMapper.selectStInfo */ SELECT a1.stdt_id AS stdtId , DATE_FORMAT(a1.subm_dt,'%Y-%m-%d %H:%i:%s') AS eakStDt , b1.DGNSS_ORD AS ordNo , CASE WHEN c1.sex = 'M' THEN '남자' ELSE '여자' END gender , `aidt_lms`.F_CODE_NM('grade_cd', e1.grade_cd) AS grade , CASE WHEN e1.cla_nm LIKE '%반' THEN e1.cla_nm WHEN e1.cla_nm IS NULL THEN '-' ELSE CONCAT(e1.cla_nm, '반') END AS classCd , a1.id AS dgnssResultId FROM `aidt_diagnosis`.`tb_dgnss_info` a1_1 INNER JOIN `aidt_diagnosis`.`tb_dgnss_result_info` a1 ON a1_1.id = a1.dgnss_id INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer` b1 ON a1.id = b1.DGNSS_RESULT_ID INNER JOIN `aidt_lms`.`user` c1 ON a1.stdt_id = c1.user_id INNER JOIN aidt_lms.stdt_reg_info e1 ON c1.user_id = e1.user_id WHERE 1=1
AND a1.stdt_id = #{stdtId} AND a1_1.paper_idx = #{paperIdx} AND a1_1.ord_no = #{ordNo}
AND a1.id = #{dgnssResultId}

/* DgnssMapper.selectFirstDgnssResultId */
SELECT b1.id
FROM aidt_diagnosis.tb_dgnss_info a1
	INNER JOIN aidt_diagnosis.tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id
WHERE a1.ord_no = 1
	AND b1.stdt_id = #{stdtId}
	AND a1.paper_idx = #{paperIdx}

/* DgnssMapper.selectStAnalysis */
SELECT CONCAT('{', GROUP_CONCAT(
	CONCAT('"', b1.SECTION_ID, '"', ' : "', IF(b1.T_SCORE < 0, 0, b1.T_SCORE), '_', b1.P_RANK, '"')), '}')
FROM aidt_diagnosis.tb_dgnss_info tdi
	INNER JOIN aidt_diagnosis.tb_dgnss_result_info tdri ON tdi.id = tdri.dgnss_id
	INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer` a1 ON tdri.id = a1.DGNSS_RESULT_ID
	INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer_report` b1 ON a1.ANSWER_IDX = b1.ANSWER_IDX
WHERE tdi.paper_idx = #{paperIdx}
	AND tdi.ord_no = #{ordNo}
	AND tdri.stdt_id = #{stdtId}

mapper.update:
/* DgnssMapper.saveDgnssTextSave */
UPDATE aidt_diagnosis.tb_dgnss_info
SET dgnss_text = #{dgnssText}
WHERE id = #{dgnssId}

mapper.select:
/* DgnssMapper.selectTcTrustInfoList */ WITH base AS ( SELECT sri.num , c1.MEM_ID AS stdtId , c1.COCH_DGNSS_QESITM01_SCORE AS q01 , c1.REPEATED_RESPONSE_YN AS repYn , c1.COCH_DGNSS_QESITM02_SCORE AS q02 FROM aidt_diagnosis.tb_dgnss_info a1 INNER JOIN aidt_diagnosis.tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN aidt_diagnosis.tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON a1.cla_id = tcmi.cla_id AND b1.stdt_id = tcmi.stdt_id AND tcmi.actvtn_at = 'Y' INNER JOIN aidt_lms.stdt_reg_info sri ON b1.stdt_id = sri.user_id WHERE a1.id = #{dgnssId} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' ) SELECT 'reaction' AS item, num, stdtId FROM base WHERE q01 > 65
UNION ALL SELECT 'repeatResponse' AS item, num, stdtId FROM base WHERE repYn = 'Y'
UNION ALL SELECT 'desirable' AS item, num, stdtId FROM base WHERE q02 > CASE WHEN #{paperIdx} = '1' THEN 65 ELSE 70 END ORDER BY item, num

/* DgnssMapper.selectDgnssIdxList */
SELECT id
FROM `aidt_diagnosis`.`tb_dgnss_info`
WHERE cla_id = #{claId}
	AND paper_idx = #{paperIdx}
	AND dgnss_at = 'N'
ORDER BY ord_no

/* DgnssMapper.selectClassTotalReport */ SELECT a1.id , a1.ord_no , CONCAT('{', GROUP_CONCAT( CONCAT('"', d1.SECTION_ID, '"', ' : ', d1.T_SCORE)), '}') AS json FROM `aidt_diagnosis`.`tb_dgnss_info` a1 INNER JOIN `aidt_diagnosis`.`tb_dgnss_result_info` b1 ON a1.id = b1.dgnss_id INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer` c1 ON b1.id = c1.DGNSS_RESULT_ID INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer_report` d1 ON c1.ANSWER_IDX = d1.ANSWER_IDX INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON a1.cla_id = tcmi.cla_id AND b1.stdt_id = tcmi.stdt_id AND tcmi.actvtn_at = 'Y' WHERE a1.id = #{dgnssId} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y'
AND c1.COCH_DGNSS_QESITM01_MARK <> '주의' AND c1.COCH_DGNSS_QESITM02_MARK <> '주의' AND c1.REPEATED_RESPONSE_YN <> 'Y'
AND IFNULL(c1.NO_ANS_CNT, 0) < 10 GROUP BY a1.`id`, b1.stdt_id

/* DgnssMapper.selectClassLernReport */ SELECT a1.id , a1.ord_no , d1.SECTION_ID , d1.`DEPTH` , e1.SECTION_NM , IF(ROUND(avg(d1.T_SCORE)) < 0, 0, ROUND(avg(d1.T_SCORE))) AS tScore FROM `aidt_diagnosis`.`tb_dgnss_info` a1 INNER JOIN `aidt_diagnosis`.`tb_dgnss_result_info` b1 ON a1.id = b1.dgnss_id INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer` c1 ON b1.id = c1.DGNSS_RESULT_ID INNER JOIN `aidt_diagnosis`.`tb_dgnss_answer_report` d1 ON c1.ANSWER_IDX = d1.ANSWER_IDX INNER JOIN `aidt_diagnosis`.`tb_dgnss_section` e1 ON d1.SECTION_ID = e1.SECTION_ID where a1.cla_id = #{claId} AND a1.paper_idx = '1' AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' AND a1.ord_no = #{ordNo}
AND c1.COCH_DGNSS_QESITM01_MARK <> '주의' AND c1.COCH_DGNSS_QESITM02_MARK <> '주의' AND c1.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY a1.id, d1.SECTION_ID

