/* DgnssMapper.selectMakePdfTargetList */ SELECT tdri.id AS answerIdx , tdri.stdt_id AS userId , 'S' AS userType FROM aidt_diagnosis.tb_dgnss_result_info tdri INNER JOIN aidt_diagnosis.tb_dgnss_info tdi ON tdri.dgnss_id = tdi.id INNER JOIN aidt_lms.tc_cla_mb_info tcmi ON tdri.stdt_id = tcmi.stdt_id AND tdi.cla_id = tcmi.cla_id AND tcmi.actvtn_at = 'Y' WHERE tdri.dgnss_id = #{dgnssId} AND tdri.subm_at = 'Y'
AND (tdri.file_url IS NULL OR tdri.file_url = '')
AND (tdri.summary_file_url IS NULL OR tdri.summary_file_url = '')
